import{_ as l,o as a,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Developer Summit - Cephadm","description":"","frontmatter":{"title":"Ceph Developer Summit - Cephadm","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","管理与优化","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_Cephadm.md","filePath":"posts/2025/Ceph_Developer_Summit_-_Cephadm.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Ceph_Developer_Summit_-_Cephadm.md"};function r(n,e,h,p,d,s){return a(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph-分布式存储会议纪要" tabindex="-1">Ceph 分布式存储会议纪要 <a class="header-anchor" href="#ceph-分布式存储会议纪要" aria-label="Permalink to &quot;Ceph 分布式存储会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>Ceph 编排（Orchestration）与存储管理讨论</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><p>Adam、John Mulligan、Redon、Anthony Datri 等</p><h4 id="关键讨论议题" tabindex="-1">关键讨论议题： <a class="header-anchor" href="#关键讨论议题" aria-label="Permalink to &quot;关键讨论议题：&quot;">​</a></h4><ol><li><p><strong>PIO3 加密库加载问题</strong>：</p><ul><li>描述：Python 加密库 <code>cryptography</code> 在多模块加载时存在冲突，导致部分模块无法接收事件。</li><li>解决方案：重构 Dashboard 和 <code>cephadm</code> 调用逻辑，避免直接导入 <code>cryptography</code>。</li><li>后续行动：由 John Mulligan 牵头，调研模块加载优化方案。</li></ul></li><li><p><strong>Python 工具链升级</strong>：</p><ul><li>现状：当前代码库依赖较旧版本的 Python 工具，无法兼容 Python 3.13+。</li><li>目标：升级至较新版本工具链，确保兼容性。</li><li>行动计划：分阶段更新工具链，优先解决 <code>cephadm</code> 的兼容性问题。</li></ul></li><li><p><strong><code>ceph</code> 命令行工具优化</strong>：</p><ul><li>问题：<code>ceph</code> CLI 代码结构混乱，缺乏维护团队。</li><li>建议方案：将部分功能迁移至 <code>python-common</code> 库，标准化代码结构。</li><li>后续行动：Adam 联系 Yuri（Manager Core 团队）讨论代码所有权问题。</li></ul></li><li><p><strong>服务配置变更自动化</strong>：</p><ul><li>背景：用户修改服务规格后需手动触发 <code>ceph orch reconfigure</code>。</li><li>提案：自动检测 Spec 变更并触发服务重配置。</li><li>技术方向：在服务类中实现字段级变更检查，支持多种响应动作。</li></ul></li><li><p><strong>密钥与证书管理</strong>：</p><ul><li>当前进展：支持通过 Vault 存储证书，但缺乏统一的 Secrets 管理框架。</li><li>未来计划：扩展后端支持，集成 ACME 协议实现自动化证书轮换。</li></ul></li><li><p><strong>大规模集群优化</strong>：</p><ul><li>性能问题：主机元数据刷新和部署任务串行执行导致延迟。</li><li>优化措施：并行化部署与删除操作，升级时结合 <code>ok-to-stop</code> 检查。</li></ul></li><li><p><strong>用户需求与功能扩展</strong>：</p><ul><li><strong>Central Config 版本控制</strong>：将集群配置纳入 Git 管理，实现基础设施即代码（IaC）。</li><li><strong>SMB 增强</strong>：支持离线域加入令牌，扩展 gRPC 接口供云平台直接管理 SMB。</li></ul></li></ol><h4 id="决议事项" tabindex="-1">决议事项： <a class="header-anchor" href="#决议事项" aria-label="Permalink to &quot;决议事项：&quot;">​</a></h4><ol><li>优先调研 K8S Events 模块的使用情况，再决定是否重构或移除。</li><li>建立定期工具链更新流程，由团队分阶段执行。</li><li>探索代码重构方案，明确维护责任。</li><li>设计服务级别的变更响应机制。</li><li>推进 ACME 协议集成，列为 Umbrella 版本目标。</li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>提交模块加载优化提案</li><li>启动 Python 工具链升级</li><li>联系 Manager Core 团队讨论 CLI 所有权</li><li>实现 Spec 变更自动化原型</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><p>需关注核心团队对 Central Config 版本控制的反馈。</p>',13)])])}const m=l(t,[["render",r]]);export{u as __pageData,m as default};
